<?php
namespace App\Http\Controllers\Api\Admin;
use App\Http\Controllers\Controller;use Illuminate\Database\Query\Builder;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Illuminate\Validation\Rule;
class EcosystemFeatureFlagController extends Controller{
 private function view(Request$r):void{abort_unless($r->user()->hasPermission('ecosystem.modules.view'),403);}private function write(Request$r):void{abort_unless($r->user()->hasPermission('ecosystem.modules.configure'),403);}
 public function dashboard(Request$r):JsonResponse{$this->view($r);$q=$this->filtered($r);$count=fn($c,$v)=>(clone$q)->where($c,$v)->count();$roll=DB::table('feature_flag_rollouts');return $this->successResponse(['dashboard'=>['summary'=>['flags'=>(clone$q)->count(),'enabled'=>$count('f.is_enabled',1),'disabled'=>$count('f.is_enabled',0),'draft'=>$count('f.status','draft'),'activeRollouts'=>(clone$roll)->where('status','active')->count(),'pausedRollouts'=>(clone$roll)->where('status','paused')->count(),'completedRollouts'=>(clone$roll)->where('status','completed')->count(),'pendingApprovals'=>$count('f.governance_status','pending')],'statuses'=>$this->distribution($q,'f.status'),'risks'=>$this->distribution($q,'f.risk_level'),'environments'=>DB::table('feature_flag_environments')->selectRaw('environment, COUNT(*) as total, SUM(CASE WHEN enabled = 1 THEN 1 ELSE 0 END) as enabled')->groupBy('environment')->get(),'rollouts'=>DB::table('feature_flag_rollouts as r')->join('feature_flags as f','f.id','=','r.feature_flag_id')->orderByDesc('r.updated_at')->limit(12)->get(['r.*','f.feature_key','f.name as flag_name']),'health'=>['score'=>null,'status'=>(clone$q)->count()?'not_evaluated':'not_evaluated','reason'=>'Runtime rollout monitoring is not configured.'],'activity'=>$this->activity(),'permissions'=>['canCreate'=>$r->user()->hasPermission('ecosystem.modules.configure'),'canUpdate'=>$r->user()->hasPermission('ecosystem.modules.configure'),'canRollout'=>$r->user()->hasPermission('ecosystem.modules.configure'),'canEmergency'=>$r->user()->hasPermission('ecosystem.modules.configure'),'canExport'=>$r->user()->hasPermission('ecosystem.modules.view')],'generatedAt'=>now()->toIso8601String()]]);}
 public function index(Request$r):JsonResponse{$this->view($r);$v=$r->validate(['search'=>['nullable','string','max:160'],'status'=>['nullable','string','max:30'],'module_id'=>['nullable','integer'],'risk'=>['nullable','string','max:20'],'environment'=>['nullable','string','max:30'],'sort'=>['nullable',Rule::in(['name','feature_key','status','risk_level','updated_at'])],'direction'=>['nullable',Rule::in(['asc','desc'])],'per_page'=>['nullable','integer','min:1','max:100']]);$q=$this->filtered($r)->select('f.id','f.uuid','f.feature_key','f.name','f.description','f.is_enabled','f.status','f.flag_type','f.owner','f.governance_status','f.risk_level','f.lock_version','f.updated_at','m.id as module_id','m.name as module_name','c.id as capability_id','c.name as capability_name')->selectSub(fn($x)=>$x->from('feature_flag_rollouts')->whereColumn('feature_flag_id','f.id')->orderByDesc('id')->limit(1)->select('status'),'rollout_status')->selectSub(fn($x)=>$x->from('feature_flag_rollouts')->whereColumn('feature_flag_id','f.id')->orderByDesc('id')->limit(1)->select('current_percentage'),'rollout_percentage');return$this->successResponse(['flags'=>$q->orderBy('f.'.($v['sort']??'updated_at'),$v['direction']??'desc')->paginate($v['per_page']??20)]);}
 public function references(Request$r):JsonResponse{$this->view($r);return$this->successResponse(['references'=>['modules'=>DB::table('ecosystem_modules')->whereNull('deleted_at')->orderBy('name')->get(['id','name']),'capabilities'=>DB::table('ecosystem_capabilities')->orderBy('name')->get(['id','ecosystem_module_id as moduleId','name']),'environments'=>['development','test','staging','production','sandbox']]]);}
 public function store(Request$r):JsonResponse{$this->write($r);$d=$this->validated($r);$id=DB::transaction(function()use($r,$d){$id=DB::table('feature_flags')->insertGetId([...$d,'uuid'=>(string)Str::uuid(),'is_enabled'=>false,'status'=>'draft','governance_status'=>'not_evaluated','risk_level'=>'unknown','lock_version'=>1,'created_by'=>$r->user()->id,'updated_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);$this->audit($id,null,$r,'created',null,$d,null);return$id;});return$this->successResponse(['flag'=>DB::table('feature_flags')->find($id)],'Feature flag created.',201);}
 public function update(Request$r,int$id):JsonResponse{$this->write($r);$flag=DB::table('feature_flags')->whereNull('deleted_at')->find($id);abort_unless($flag,404);$d=$r->validate(['name'=>['sometimes','string','max:160'],'description'=>['sometimes','nullable','string'],'owner'=>['sometimes','nullable','string','max:160'],'status'=>['sometimes',Rule::in(['draft','active','inactive','archived'])],'governance_status'=>['sometimes',Rule::in(['not_evaluated','pending','approved','rejected'])],'risk_level'=>['sometimes',Rule::in(['unknown','low','medium','high','critical'])],'lock_version'=>['required','integer']]);abort_if((int)$d['lock_version']!==$flag->lock_version,409,'Flag was changed by another administrator.');unset($d['lock_version']);DB::transaction(function()use($r,$id,$flag,$d){DB::table('feature_flags')->where('id',$id)->update([...$d,'lock_version'=>$flag->lock_version+1,'updated_by'=>$r->user()->id,'updated_at'=>now()]);$this->audit($id,null,$r,'updated',(array)$flag,$d,null);});return$this->successResponse(['flag'=>DB::table('feature_flags')->find($id)]);}
 public function environment(Request$r,int$id):JsonResponse{$this->write($r);$d=$r->validate(['environment'=>['required',Rule::in(['development','test','staging','production','sandbox'])],'enabled'=>['required','boolean'],'value'=>['nullable'],'rollout_percentage'=>['required','integer','min:0','max:100']]);$flag=DB::table('feature_flags')->whereNull('deleted_at')->find($id);abort_unless($flag,404);DB::transaction(function()use($r,$id,$d,$flag){$before=DB::table('feature_flag_environments')->where('feature_flag_id',$id)->where('environment',$d['environment'])->first();DB::table('feature_flag_environments')->updateOrInsert(['feature_flag_id'=>$id,'environment'=>$d['environment']],[...$d,'value'=>isset($d['value'])?json_encode($d['value']):null,'created_at'=>$before?->created_at??now(),'updated_at'=>now()]);$this->audit($id,null,$r,'environment_configured',$before?(array)$before:null,$d,null);});return$this->successResponse(message:'Environment configuration saved.');}
 public function rollout(Request$r,int$id):JsonResponse{$this->write($r);$d=$r->validate(['environment'=>['required',Rule::in(['development','test','staging','production','sandbox'])],'strategy'=>['required',Rule::in(['percentage','targeted','scheduled','all'])],'target_percentage'=>['required','integer','min:0','max:100'],'targeting'=>['nullable','array'],'stages'=>['nullable','array'],'reason'=>['nullable','string','max:1000']]);abort_unless(DB::table('feature_flags')->whereNull('deleted_at')->where('id',$id)->exists(),404);$roll=DB::transaction(function()use($r,$id,$d){$rid=DB::table('feature_flag_rollouts')->insertGetId([...$d,'feature_flag_id'=>$id,'uuid'=>(string)Str::uuid(),'status'=>'draft','current_percentage'=>0,'targeting'=>isset($d['targeting'])?json_encode($d['targeting']):null,'stages'=>isset($d['stages'])?json_encode($d['stages']):null,'lock_version'=>1,'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);$this->audit($id,$rid,$r,'rollout_created',null,$d,$d['reason']??null);return DB::table('feature_flag_rollouts')->find($rid);});return$this->successResponse(['rollout'=>$roll],'Rollout created.',201);}
 public function transition(Request$r,int$id,int$rollout):JsonResponse{$this->write($r);$d=$r->validate(['action'=>['required',Rule::in(['start','advance','pause','resume','complete','rollback'])],'percentage'=>['nullable','integer','min:0','max:100'],'reason'=>['nullable','string','max:1000'],'lock_version'=>['required','integer']]);$row=DB::table('feature_flag_rollouts')->where('id',$rollout)->where('feature_flag_id',$id)->first();abort_unless($row,404);abort_if((int)$d['lock_version']!==$row->lock_version,409,'Rollout was changed by another administrator.');$allowed=['start'=>['draft'],'advance'=>['active'],'pause'=>['active'],'resume'=>['paused'],'complete'=>['active'],'rollback'=>['active','paused','completed']];abort_unless(in_array($row->status,$allowed[$d['action']],true),409,'Invalid rollout transition.');$status=['start'=>'active','advance'=>'active','pause'=>'paused','resume'=>'active','complete'=>'completed','rollback'=>'rolled_back'][$d['action']];$pct=$d['action']==='rollback'?0:($d['action']==='complete'?$row->target_percentage:($d['percentage']??$row->current_percentage));abort_if($pct>$row->target_percentage,422,'Percentage cannot exceed rollout target.');DB::transaction(function()use($r,$id,$rollout,$row,$d,$status,$pct){DB::table('feature_flag_rollouts')->where('id',$rollout)->update(['status'=>$status,'current_percentage'=>$pct,'reason'=>$d['reason']??$row->reason,'started_at'=>$d['action']==='start'?now():$row->started_at,'completed_at'=>$d['action']==='complete'?now():$row->completed_at,'lock_version'=>$row->lock_version+1,'updated_at'=>now()]);DB::table('feature_flag_environments')->updateOrInsert(['feature_flag_id'=>$id,'environment'=>$row->environment],['enabled'=>$status==='active'||$status==='completed','rollout_percentage'=>$pct,'created_at'=>now(),'updated_at'=>now()]);$this->audit($id,$rollout,$r,'rollout_'.$d['action'],(array)$row,['status'=>$status,'percentage'=>$pct],$d['reason']??null);});return$this->successResponse(['rollout'=>DB::table('feature_flag_rollouts')->find($rollout)]);}
 public function emergency(Request$r,int$id):JsonResponse{$this->write($r);$d=$r->validate(['reason'=>['required','string','min:10','max:1000']]);$flag=DB::table('feature_flags')->whereNull('deleted_at')->find($id);abort_unless($flag,404);DB::transaction(function()use($r,$id,$flag,$d){DB::table('feature_flags')->where('id',$id)->update(['is_enabled'=>false,'risk_level'=>'critical','updated_by'=>$r->user()->id,'updated_at'=>now()]);DB::table('feature_flag_environments')->where('feature_flag_id',$id)->update(['enabled'=>false,'rollout_percentage'=>0,'updated_at'=>now()]);DB::table('feature_flag_rollouts')->where('feature_flag_id',$id)->whereIn('status',['active','paused'])->update(['status'=>'rolled_back','current_percentage'=>0,'reason'=>$d['reason'],'updated_at'=>now()]);$this->audit($id,null,$r,'emergency_disabled',(array)$flag,['is_enabled'=>false],$d['reason']);});return$this->successResponse(message:'Feature flag disabled in all configured environments.');}
 public function export(Request$r):JsonResponse{$this->view($r);return response()->json(['source'=>'database','generatedAt'=>now()->toIso8601String(),'flags'=>$this->filtered($r)->select('f.*')->get(),'environments'=>DB::table('feature_flag_environments')->get(),'rollouts'=>DB::table('feature_flag_rollouts')->get()]);}
 private function filtered(Request$r):Builder{$q=DB::table('feature_flags as f')->leftJoin('ecosystem_modules as m','m.id','=','f.ecosystem_module_id')->leftJoin('ecosystem_capabilities as c','c.id','=','f.capability_id')->whereNull('f.deleted_at');if($s=trim((string)$r->search))$q->where(fn($x)=>$x->where('f.name','like',"%$s%")->orWhere('f.feature_key','like',"%$s%"));foreach(['status'=>'f.status','module_id'=>'f.ecosystem_module_id','risk'=>'f.risk_level']as$k=>$c)if($r->filled($k))$q->where($c,$r->$k);if($r->filled('environment'))$q->whereExists(fn($x)=>$x->selectRaw(1)->from('feature_flag_environments as e')->whereColumn('e.feature_flag_id','f.id')->where('e.environment',$r->environment));return$q;}
 private function validated(Request$r):array{return$r->validate(['feature_key'=>['required','alpha_dash','max:160','unique:feature_flags,feature_key'],'name'=>['required','string','max:160'],'description'=>['nullable','string'],'ecosystem_module_id'=>['nullable','integer','exists:ecosystem_modules,id'],'capability_id'=>['nullable','integer','exists:ecosystem_capabilities,id'],'flag_type'=>['required',Rule::in(['boolean','string','number','json'])],'owner'=>['nullable','string','max:160']]);}private function distribution(Builder$q,string$c){return(clone$q)->select($c.' as key',DB::raw('COUNT(*) as count'))->groupBy($c)->get();}private function activity(){return DB::table('feature_flag_audits as a')->leftJoin('users as u','u.id','=','a.actor_id')->join('feature_flags as f','f.id','=','a.feature_flag_id')->orderByDesc('a.created_at')->limit(15)->get(['a.id','a.feature_flag_id','a.rollout_id','a.action','a.reason','u.name as actor','f.name as flag_name','a.created_at']);}private function audit(int$f,?int$roll,Request$r,string$a,?array$b,?array$after,?string$reason):void{DB::table('feature_flag_audits')->insert(['feature_flag_id'=>$f,'rollout_id'=>$roll,'action'=>$a,'actor_id'=>$r->user()->id,'reason'=>$reason,'before'=>$b?json_encode($b):null,'after'=>$after?json_encode($after):null,'created_at'=>now()]);}
}
